"""Pydantic schemas for meal analysis requests, responses, and health checks."""

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, ConfigDict, Field


class MealAnalysisRaw(BaseModel):
    """Raw structured response generated by Google Gemini."""

    model_config = ConfigDict(extra="ignore")

    isFood: bool = Field(description="Whether the user input describes or depicts food/drink")
    foodName: Optional[str] = Field(default="Unknown meal", description="Name and portion of the meal")
    calories: Optional[str] = Field(default="N/A", description="Estimated calorie count with units")
    protein: Optional[str] = Field(default="N/A", description="Estimated protein with units")
    carbs: Optional[str] = Field(default="N/A", description="Estimated carbohydrates with units")
    fat: Optional[str] = Field(default="N/A", description="Estimated fat with units")
    healthScore: Optional[Any] = Field(default=None, description="Score between 0 and 100")
    scoreReason: Optional[str] = Field(default="", description="Short reason for the score")
    suggestions: List[str] = Field(default_factory=list, description="Healthy meal suggestions")
    goalTips: Optional[Dict[str, str]] = Field(default_factory=dict, description="Tips by fitness goal")


class MealAnalysisResponse(BaseModel):
    """Normalized response schema returned to the web frontend."""

    model_config = ConfigDict(populate_by_name=True)

    food_name: str = Field(description="Detected meal name and portion")
    calories: str = Field(description="Estimated calorie count")
    protein: str = Field(description="Estimated protein grams")
    carbs: str = Field(description="Estimated carb grams")
    fat: str = Field(description="Estimated fat grams")
    score: str = Field(description="Formatted health score e.g. 85/100")
    suggestions: List[str] = Field(description="Actionable meal improvements")
    goalTips: Dict[str, str] = Field(description="Tips mapped by goal")
    scoreReason: str = Field(description="Reasoning behind the health score")
    model_used: Optional[str] = Field(default=None, alias="_modelUsed", serialization_alias="_modelUsed")


class HealthStatusResponse(BaseModel):
    """Health check endpoint schema."""

    status: str = "ok"
    preferredModel: str
    availableFallbackModels: List[str]


class ErrorResponse(BaseModel):
    """Consistent error payload."""

    error: str
